WITH relevant_procedures AS (SELECT p.subject_id, COUNT(DISTINCT i.itemid) AS num_procedures FROM patients p JOIN procedures_icd i ON p.subject_id = i.subject_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM AGE(p.dob)) = 1972 AND EXTRACT(YEAR FROM AGE(p.dob)) BETWEEN 1943 AND 1953 AND i.icd_code IN ('470170', '470171', '470172', '470173', '470174', '470175', '470176', '470177', '470178', '470179') GROUP BY p.subject_id) SELECT percentile_cont(0.25) within GROUP (ORDER BY num_procedures) AS percentile FROM relevant_procedures;